def P(z):
    return z**3 - 32*z**2 + 72

# Divisors of 72 in the range [4, 63]
divisors = [d for d in [1, 2, 3, 4, 6, 8, 9, 12, 18, 24, 36, 72] if 4 <= d < 64]

solutions = []
for z in divisors:
    if P(z) == 0:
        solutions.append(z)

print(f"Tested divisors: {divisors}")
print(f"Integer solutions found: {solutions}")
